// Generated by AI (UnitTest MCP)
import { describe, expect, it } from "vitest";

import {
  doctorAilmentIcon,
  doctorAilmentLabel,
  doctorGroups,
  fleetDashboard,
  formatDuration,
  shortAgent,
  verbsForTask,
  type BoardFinding,
  type FleetInput,
  type FleetSnapshot,
} from "./fleet";
import type { LodestarTask } from "./util";

const NOW = 1_786_685_000;
const SELF = "session:v1:f29019a0fe7f8d29c7e67e0663bc95ea";
const PEER = "session:v1:07f6a91b3b4894f4aed18823dc9a3b1f";

function task(overrides: Partial<LodestarTask> = {}): LodestarTask {
  return {
    id: "task:abc123",
    goal_id: "goal:g@constitution:v4",
    title: "Some work",
    status: "claimed",
    owner: SELF,
    claim_started_at: NOW - 600,
    lease_expires_at: NOW + 600,
    ...overrides,
  };
}

function snapshot(sessions: FleetSnapshot["sessions"]): FleetSnapshot {
  return {
    sessions,
    divergence: { bases: ["origin/main"], diverged: false, undeclared_sessions: 0 },
  };
}

function input(overrides: Partial<FleetInput> = {}): FleetInput {
  return {
    planes: { intent: true, memory: true },
    selfAgentId: SELF,
    nowUnix: NOW,
    ...overrides,
  };
}

describe("shortAgent", () => {
  it("keeps the last twelve fingerprint characters so agents stay distinguishable", () => {
    expect(shortAgent(SELF)).toBe("7e0663bc95ea");
  });

  it("returns a short id unchanged rather than padding it", () => {
    expect(shortAgent("session:v1:abc")).toBe("abc");
  });
});

describe("verbsForTask", () => {
  it("offers renew, release and pause on this session's live claim", () => {
    expect(verbsForTask(task(), true, NOW)).toStrictEqual(["renew", "release", "pause"]);
  });

  it("offers nothing on this session's own lapsed claim, because renew is refused after expiry", () => {
    expect(verbsForTask(task({ lease_expires_at: NOW - 1 }), true, NOW)).toStrictEqual([]);
  });

  it("offers resume on this session's paused task", () => {
    expect(verbsForTask(task({ status: "paused" }), true, NOW)).toStrictEqual(["resume"]);
  });

  it("offers no verb on a peer's live claim, so a held task cannot be taken", () => {
    expect(verbsForTask(task({ owner: PEER }), false, NOW)).toStrictEqual([]);
  });

  it("offers an ordinary claim on a peer's lapsed session claim, not recover", () => {
    const lapsed = task({ owner: PEER, lease_expires_at: NOW - 1 });
    expect(verbsForTask(lapsed, false, NOW)).toStrictEqual(["claim"]);
  });

  it("offers recover only for a stranded legacy identity", () => {
    const legacy = task({ owner: "copilot-abcd1234", lease_expires_at: NOW - 1 });
    expect(verbsForTask(legacy, false, NOW)).toStrictEqual(["recover"]);
  });
});

describe("fleetDashboard", () => {
  it("marks this session and renders a live lease with its remaining seconds", () => {
    const board = fleetDashboard(
      input({
        snapshot: snapshot([
          {
            agent_id: SELF,
            context: {
              branch: "feat/fleet-view",
              head_sha: "d225a23",
              base: "origin/main",
              behind: 0,
              dirty: false,
            },
            declared_at: NOW - 30,
          },
        ]),
        tasks: [task()],
      })
    );

    expect(board.rows).toHaveLength(1);
    const row = board.rows[0];
    expect(row.isSelf).toBe(true);
    expect(row.branch).toBe("feat/fleet-view");
    expect(row.state).toBe("holding");
    expect(row.tasks[0].lease).toBe("live");
    expect(row.tasks[0].leaseSeconds).toBe(600);
    expect(row.tasks[0].verbs).toStrictEqual(["renew", "release", "pause"]);
  });

  it("renders a lapsed peer claim as reclaimable and sorts it above idle agents", () => {
    const board = fleetDashboard(
      input({
        snapshot: snapshot([
          { agent_id: PEER, context: { branch: "main" }, declared_at: NOW - 100 },
          { agent_id: "session:v1:idle0000000000000000000000000000", declared_at: NOW - 10 },
        ]),
        tasks: [task({ owner: PEER, lease_expires_at: NOW - 90 })],
      })
    );

    expect(board.rows.map((row) => row.state)).toStrictEqual(["lapsed", "idle"]);
    expect(board.rows[0].tasks[0].lease).toBe("expired");
    expect(board.rows[0].tasks[0].leaseSeconds).toBe(-90);
    expect(board.rows[0].tasks[0].verbs).toStrictEqual(["claim"]);
  });

  it("reports an undeclared branch as unknown rather than guessing one", () => {
    const board = fleetDashboard(
      input({
        snapshot: snapshot([{ agent_id: SELF, context: { branch: "   " }, declared_at: NOW }]),
      })
    );

    expect(board.rows[0].branch).toBeNull();
    expect(board.rows[0].head).toBeNull();
    expect(board.rows[0].dirty).toBeNull();
    expect(board.rows[0].behind).toBeNull();
  });

  it("hides sessions idle beyond the window but never one that holds work", () => {
    const board = fleetDashboard(
      input({
        selfAgentId: null,
        snapshot: snapshot([
          { agent_id: PEER, declared_at: NOW - 99_999 },
          { agent_id: "session:v1:holder00000000000000000000000000", declared_at: NOW - 99_999 },
        ]),
        tasks: [task({ owner: "session:v1:holder00000000000000000000000000" })],
        activeWindowSeconds: 1800,
      })
    );

    expect(board.rows.map((row) => row.agentId)).toStrictEqual([
      "session:v1:holder00000000000000000000000000",
    ]);
    expect(board.hidden).toBe(1);
  });

  it("degrades to an explicit notice instead of presenting a stale roster when Lodestar is down", () => {
    const board = fleetDashboard(
      input({
        planes: { intent: false, memory: true },
        snapshot: snapshot([{ agent_id: SELF, declared_at: NOW }]),
        tasks: [task()],
      })
    );

    expect(board.rows).toStrictEqual([]);
    expect(board.notice).toBe("Lodestar is not answering, so no roster or claim is shown.");
  });

  it("names the memory plane separately, because observed activity is the part that goes missing", () => {
    const board = fleetDashboard(
      input({
        planes: { intent: true, memory: false },
        snapshot: snapshot([{ agent_id: SELF, declared_at: NOW }]),
      })
    );

    expect(board.rows).toHaveLength(1);
    expect(board.rows[0].observations).toBeNull();
    expect(board.notice).toBe("MindLeak is not answering, so observed activity is missing.");
  });

  it("joins MindLeak observation counts onto the session that earned them", () => {
    const board = fleetDashboard(
      input({
        snapshot: snapshot([{ agent_id: SELF, declared_at: NOW - 10 }]),
        roster: { agents: [{ id: `agent:${SELF}`, last_active: NOW - 5, observations: 42 }] },
      })
    );

    expect(board.rows[0].observations).toBe(42);
    expect(board.rows[0].lastActive).toBe(NOW - 5);
  });

  it("survives a plane answering with nothing at all", () => {
    const board = fleetDashboard(input({ snapshot: null, roster: null, tasks: null }));

    expect(board.rows).toStrictEqual([]);
    expect(board.hidden).toBe(0);
    expect(board.notice).toBeNull();
    expect(board.divergence.bases).toStrictEqual([]);
  });
});

describe("formatDuration", () => {
  it("renders an unknown span as unknown rather than zero", () => {
    expect(formatDuration(null)).toBe("unknown");
  });

  it("renders each magnitude in its own unit", () => {
    expect(formatDuration(45)).toBe("45s");
    expect(formatDuration(600)).toBe("10m");
    expect(formatDuration(7200)).toBe("2h");
    expect(formatDuration(172_800)).toBe("2d");
  });

  it("renders a lapsed span by magnitude, so the sign is the caller's to show", () => {
    expect(formatDuration(-90)).toBe("1m");
  });
});

function boardFinding(overrides: Partial<BoardFinding> = {}): BoardFinding {
  return {
    ailment: "duplicate_title",
    subject: "Some title",
    remedy: "decide which is the work",
    task_ids: ["task:1"],
    ...overrides,
  };
}

describe("doctorAilmentLabel", () => {
  it("names each known ailment in plain language", () => {
    expect(doctorAilmentLabel("duplicate_title")).toBe("Duplicate title");
    expect(doctorAilmentLabel("same_title_across_goals")).toBe("Forked across goals");
    expect(doctorAilmentLabel("blocked_without_gate")).toBe("Blocked with no gate");
  });

  it("falls back to the raw ailment for one it does not recognise", () => {
    expect(doctorAilmentLabel("something_new")).toBe("something_new");
  });
});

describe("doctorAilmentIcon", () => {
  it("gives every known ailment its own icon", () => {
    expect(doctorAilmentIcon("blocked_without_gate")).toBe("circle-slash");
    expect(doctorAilmentIcon("same_title_across_goals")).toBe("type-hierarchy");
    expect(doctorAilmentIcon("duplicate_title")).toBe("copy");
  });

  it("falls back to a question mark for one it does not recognise", () => {
    expect(doctorAilmentIcon("something_new")).toBe("question");
  });
});

describe("doctorGroups", () => {
  it("groups findings by ailment, worst-first", () => {
    const groups = doctorGroups([
      boardFinding({ ailment: "duplicate_title" }),
      boardFinding({ ailment: "blocked_without_gate" }),
      boardFinding({ ailment: "same_title_across_goals" }),
      boardFinding({ ailment: "duplicate_title" }),
    ]);

    expect(groups.map((group) => group.ailment)).toEqual([
      "blocked_without_gate",
      "same_title_across_goals",
      "duplicate_title",
    ]);
    expect(groups.find((group) => group.ailment === "duplicate_title")?.findings).toHaveLength(2);
  });

  it("omits an ailment with no findings rather than an empty group", () => {
    const groups = doctorGroups([boardFinding({ ailment: "duplicate_title" })]);

    expect(groups).toHaveLength(1);
  });

  it("sorts an unrecognised ailment last", () => {
    const groups = doctorGroups([
      boardFinding({ ailment: "blocked_without_gate" }),
      boardFinding({ ailment: "a_future_ailment" }),
    ]);

    expect(groups.map((group) => group.ailment)).toEqual([
      "blocked_without_gate",
      "a_future_ailment",
    ]);
  });

  it("returns nothing for an empty findings list", () => {
    expect(doctorGroups([])).toEqual([]);
  });
});
